pub fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert_eq!(s2.len(), n, "s2 must have the same length as s1");
    assert_eq!(s3.len(), n, "s3 must have the same length as s1");

    let cap = n.checked_mul(3).expect("3 * n overflowed usize");
    let mut res = Vec::with_capacity(cap);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}